INSERT INTO problems (slug,leetcode_id,title,description,difficulty,source_url,topics,companies,company_count,popularity,acceptance,recency,description_source,embedding) VALUES ('sliding-window-maximum',239,'Sliding Window Maximum','You are given an array of integers nums , there is a sliding window of size k which is moving from the very left of the array to the very right. You can only see the k numbers in the window. Each time the sliding window moves right by one position.

Return the max sliding window .

Example 1:

Input: nums = [1,3,-1,-3,5,3,6,7], k = 3
Output: [3,3,5,5,6,7]
Explanation:
Window position Max
--------------- -----
[1 3 -1] -3 5 3 6 7 3
1 [3 -1 -3] 5 3 6 7 3
1 3 [-1 -3 5] 3 6 7 5
1 3 -1 [-3 5 3] 6 7 5
1 3 -1 -3 [5 3 6] 7 6
1 3 -1 -3 5 [3 6 7] 7

Example 2:

Input: nums = [1], k = 1
Output: [1]

Constraints:

- 1 <= nums.length <= 10^5

- -10^4 <= nums[i] <= 10^4

- 1 <= k <= nums.length','hard','https://leetcode.com/problems/sliding-window-maximum','{"Array","Queue","Sliding Window","Heap (Priority Queue)","Monotonic Queue","Range Minimum/Maximum Query"}','{"adobe","agoda","amazon","apple","aurora","autodesk","blinkit","bloomberg","bookingcom","bytedance","cisco","citadel","coupang","de-shaw","doordash","expedia","faire","gameskraft","gojek","goldman-sachs","google","ibm","jpmorgan","juspay","line","meta","microsoft","mongodb","nutanix","nvidia","oracle","palo-alto-networks","phonepe","roblox","salesforce","servicenow","sprinklr","tcs","tiktok","uber","visa","walmart-labs","wayfair","yandex","zenefits","zepto","zeta","zoho"}',48,2900.0,49.0,'30d','leetcode','[-0.020567792, 0.0051277685, 0.008777904, -0.081534296, -0.03203802, -0.004663244, 0.011104346, 0.001557074, 0.01570417, -0.0065291463, -0.00901906, -0.0028947818, 0.022753421, 0.00065291644, 0.1290875, 0.007082072, -0.022216985, 0.02267331, 0.0049083508, -0.010326829, 0.021423433, -0.0036860795, 0.04901429, -0.0028027948, -0.0030658694, 0.00724408, 0.01971078, 0.0064791827, 0.019304387, 0.024848068, 0.011903489, 0.026553927, 0.006535309, 0.004216974, 0.0012481257, -0.0035697096, 0.018294495, -0.005974419, -0.0022433698, 0.0073425556, 0.0013686223, -0.008877317, 0.0049612126, -0.02530374, -0.021885509, 0.0039005773, -0.007833397, -0.023732783, 0.018447746, -0.013560434, -0.0032138622, 0.034787763, -0.008732929, -0.1882789, 0.018824086, 0.035406366, -0.0075699836, 0.0124474205, -0.025299698, -0.011031346, -0.0038690981, 0.016429575, -0.013288283, -0.0054596458, 0.007291385, 0.0017140358, 0.018949702, 0.018612176, -0.027395967, -0.031305008, 0.023558145, -0.0023980208, 0.026531305, -0.009237103, -0.0022475543, 0.005852659, 0.02831714, -0.01890757, -0.02734774, 0.02512576, -0.017828094, 0.021953251, 0.0069034314, -0.020262264, -0.009777119, 0.017066376, -0.017165607, -0.005014521, 0.010504768, 0.00025923536, -0.025446065, -0.017748324, 0.00803156, 0.0005309553, 0.0054391488