INSERT INTO problems (slug,leetcode_id,title,description,difficulty,source_url,topics,companies,company_count,popularity,acceptance,recency,description_source,embedding) VALUES ('meeting-rooms-ii',253,'Meeting Rooms II','Given an array of meeting time intervals where intervals[i] = [start_i, end_i], return the minimum number of conference rooms required to hold all meetings. A single conference room can host at most one meeting at any given time. If two meetings overlap in time, they require separate rooms. Input is a 2D array of integers. Constraints: interval array length is typically between 1 and 10,000, and times are non-negative integers up to 1,000,000 with start_i < end_i.','medium','https://leetcode.com/problems/meeting-rooms-ii','{"Array","Two Pointers","Greedy","Sorting","Heap (Priority Queue)","Prefix Sum"}','{"adobe","amazon","anduril","apple","atlassian","aurora","bloomberg","capital-one","cisco","citadel","compass","disney","docusign","freshworks","google","hubspot","ibm","jpmorgan","lime","lyft","meta","microsoft","morgan-stanley","netflix","nutanix","oracle","pinterest","salesforce","snapchat","snowflake","splunk","tekion","tiktok","two-sigma","uber","visa","walmart-labs","waymo","wells-fargo","whatnot","worldquant","yahoo"}',42,2662.5,52.7,'3mo','gemini','[0.006113991, 0.008124068, -0.0026806912, -0.0696924, -0.023766244, -0.018549934, -0.0048608044, -0.0011743023, 0.0060649314, 0.012965682, 0.0007946328, 0.0024894888, 0.016116982, -0.009675088, 0.13895884, 0.01772629, 0.0013908301, 0.006438456, 0.025520813, -0.018161213, -0.008360563, 0.0144811105, -0.0017931617, -0.0114703225, -0.011498831, -0.008165104, 0.01626115, -0.008426406, 0.036226258, 0.044250283, 0.016593771, 0.020358192, 0.0019729617, 0.039624926, 0.019561777, -0.014543657, 0.0041482053, -0.0034362886, -0.010840351, 0.01855183, 0.019886421, 0.0005004102, 0.0015893755, -0.03260159, -0.04066071, 0.00832346, 0.00047584713, -0.04470812, -0.002520179, 0.004310181, 0.0022565022, 0.016758287, 