INSERT INTO problems (slug,leetcode_id,title,description,difficulty,source_url,topics,companies,company_count,popularity,acceptance,recency,description_source,embedding) VALUES ('design-hit-counter',362,'Design Hit Counter','Design a hit counter that counts the number of hits received in the past 5 minutes (300 seconds). Implement the HitCounter class with hit(timestamp) to record a hit at the given timestamp in seconds, and getHits(timestamp) to return the total number of hits received in the time range [timestamp - 299, timestamp]. Timestamps are given in chronological order (monotonically increasing).','medium','https://leetcode.com/problems/design-hit-counter','{"Array","Hash Table","Binary Search","Design","Queue"}','{"affirm","amazon","apple","atlassian","bloomberg","careem","cloudflare","coupang","databricks","dropbox","google","meta","microsoft","openai","oracle","oscar-health","reddit","roblox","sentry","snapchat","snowflake","uber","walmart-labs","wise","yandex"}',25,1437.5,69.7,'30d','gemini','[-0.024052937, 0.020316372, -0.0014401488, -0.08793228, -0.0254508, -0.01724304, 0.007695132, -0.014228733, 0.016902514, -0.022087779, -0.014259522, -0.010755492, -0.0012807273, -0.003751343, 0.12642454, 0.026781874, -0.028603394, -0.004432402, 0.002847157, -0.0055642817, -0.025523707, 0.034639515, 0.038423583, -0.01731085, 0.005288059, -0.012571492, 0.0321341, -0.010952314, 0.036421508, 0.013036712, -0.015860034, 0.023087332, 0.014786865, 0.031631954, -0.018303301, 0.007096398, 0.03356022, -0.0006475924, -0.006960771, 0.029636778, 0.013971161, -0.005736342, 0.022797989, -0.0113778105, -0.027780566, 0.017740795, -0.0069554066, -0.0003471462, -0.0017721824, -0.0025556507, -0.0037348114, 0.023650203, -0.0068705822, -0.18021579, 0.008033236, 0.006969904, -0.021181496, -0.002529935, -0.023775183, -0.033778843, -0.008655097, 0.013058669, -0.034091394, -0.007985192, 0.0013030128, -0.00020188278, 0.0029708266, 0.0034586242, -0.026039826, -0.0113989785, -0.014526605, 0.0035