INSERT INTO problems (slug,leetcode_id,title,description,difficulty,source_url,topics,companies,company_count,popularity,acceptance,recency,description_source,embedding) VALUES ('logger-rate-limiter',359,'Logger Rate Limiter','Design a logger system that receives a stream of messages along with their timestamps and decides whether each message should be printed. A message should be printed at most once every 10 seconds. That is, if a message arrives at timestamp t and is printed, the same message cannot be printed again until timestamp t + 10. Implement the Logger class with the method shouldPrintMessage(int timestamp, string message), which returns true if the message should be printed at the given timestamp, and false otherwise. Timestamps are passed in non-decreasing order.','easy','https://leetcode.com/problems/logger-rate-limiter','{"Hash Table","Design"}','{"amazon","appfolio","apple","atlassian","cloudflare","deliveroo","docusign","google","grammarly","intuit","meta","microsoft","netflix","oracle","palo-alto-networks","patreon","reddit","roblox","tesla","verily","waymo"}',21,1275.0,76.9,'3mo','gemini','[-0.014360042, 0.013953447, -0.0038989943, -0.055952944, -0.0085204365, -0.014451681, 0.0034768167, 0.0050216955, 0.022605008, -0.0070209475, -0.026932796, -0.016819287, 0.0014075582, -0.005909439, 0.13281794, 0.034618333, -0.023997974, 0.013664327, -0.0018456333, -0.004745218, -0.0320285, 0.015035819, 0.020694314, -0.01972453, -0.004431593, -0.007750439, 0.02747311, -0.016602349, 0.036397614, 0.016311834, -0.015302096, 0.029138144, 0.018370781, 0.04322227, 0.008692078, 0.024044808, 0.04545413, -0.009716626, -0.007297884, 0.015444983, -0.0047725914, 9.9123405e-05, 0.031606674, -0.009284562, -0.00058936427, 0.027906518, 0.00020344877, 0.027893262, -0.013408955, 0.03100078, 0.0011121759, 0.009345943, -0.009313498, -0.17849389, 0.0075173248, 0.01646209, -0.012886724, 0.0111352, -0.009437204, -0.025506739, -0.018469706, 0.00692081, -0.03207243, -0.036526255, 0.0194