INSERT INTO problems (slug,leetcode_id,title,description,difficulty,source_url,topics,companies,company_count,popularity,acceptance,recency,description_source,embedding) VALUES ('alien-dictionary',269,'Alien Dictionary','You are given a list of strings words from the alien language''s dictionary, where the strings are sorted lexicographically according to the rules of this new language. Return a string of the unique letters in the alien language sorted in lexicographically increasing order by the new language''s rules. If there is no valid ordering of letters (e.g., due to a cycle or an invalid prefix order), return an empty string "". If multiple valid orderings exist, return any of them. Constraints: 1 <= words.length <= 100, 1 <= words[i].length <= 100, and words[i] consists of lowercase English letters.','hard','https://leetcode.com/problems/alien-dictionary','{"Array","String","Depth-First Search","Breadth-First Search","Graph","Topological Sort"}','{"airbnb","amazon","apple","bloomberg","coupang","ebay","google","meta","microsoft","nuro","pocket-gems","snapchat","tiktok","twitter","uber","waymo","wix"}',17,1037.5,37.3,'30d','gemini','[-0.019872269, 0.012124866, 0.013681909, -0.07070792, -0.02543062, 0.017278172, 0.014788017, -0.012777745, 0.011424487, -0.008332518, -0.031658046, -0.021688852, -0.00030153545, 0.015454536, 0.13897344, 0.0026546277, 7.125863e-05, 0.04409469, -0.0036535505, -0.021417074, 0.0033867299, -0.0048349686, 0.014941238, 0.0010788753, -0.019375829, -0.029932927, 0.0011718033, 0.0017179816, 0.023483204, 0.011837895, 0.020406062, 0.042147093, -0.0037646228, 0.018270692, 0.02447061, -0.0046137176, 0.006026824, -0.011711444, -0.0011339473, -0.004691994, 0.0134799145, 0.021038394, 0.010053055, -0.02930261, -0.0031730726, -0.00054910866, 0.011673465, -0.00052461686, 0.009708916, 0.019292446, 0.0032454254, 0.018178372, 0.0061016777, -0.17635243, -0.015122686, 0.0018217684, 0.02412452, -0.011465433, -0.012220022, 0.009808095, 0.011480526, 0.021606