INSERT INTO problems (slug,leetcode_id,title,description,difficulty,source_url,topics,companies,company_count,popularity,acceptance,recency,description_source,embedding) VALUES ('shortest-distance-from-all-buildings',317,'Shortest Distance from All Buildings','You are given an m x n grid of values 0, 1, or 2, where 0 represents an empty land, 1 represents a building, and 2 represents an obstacle. You want to build a house on an empty land that has the shortest total travel distance to all buildings. You can only move up, down, left, and right through empty lands. Return the minimum total travel distance. If it is not possible to reach all buildings from any empty land, return -1. Constraints: m and n are between 1 and 50, and there is at least one building.','hard','https://leetcode.com/problems/shortest-distance-from-all-buildings','{"Array","Breadth-First Search","Matrix"}','{"amazon","apple","applied-intuition","bloomberg","bytedance","doordash","glean","google","meta","microsoft","tiktok","uber","waymo","wix","zenefits"}',15,737.5,45.0,'6mo','gemini','[-0.025519228, -0.025322646, 0.030139405, -0.08149178, -0.014248919, -0.021451786, 0.01269639, -0.025669891, 0.013994472, -0.006157742, -0.0071738856, -0.0052139005, 0.013505329, 0.005709484, 0.15245928, 0.0065981615, 0.010959684, 0.018013088, 0.01314231, 0.0037750902, -0.004829338, 0.006995462, 0.022144718, 0.0037136069, -0.03794199, -0.008645192, -0.013367508, 0.03822136, 0.0070226244, -0.009798391, 0.008336712, 0.03200522, 0.0062625357, 0.04756375, 0.012640834, 0.0004691086, 0.0045610075, -0.019408405, 0.014534239, -0.007174032, 0.020195628, 0.0045283386, 0.023217553, -0.01651861, -0.029927963, -0.0102153635, -0.017543918, -0.027758395, -0.0069005787, 0.006031291, -0.019316778, 0.0066684918, -0.009666304, -0.18230347, 0.0022898312, -0.008887776, 0.023490375, -0.014145625, -0.02642163, 0.012661432, 0.0034232992, 0.01928022, 0.012886559, -0.006771106, -0.0035688323, 0.0061614793, 0.019913848, 0.029476736, -0.02154