INSERT INTO problems (slug,leetcode_id,title,description,difficulty,source_url,topics,companies,company_count,popularity,acceptance,recency,description_source,embedding) VALUES ('optimal-account-balancing',465,'Optimal Account Balancing','You are given a list of transactions between a group of people, where transactions[i] = [from, to, amount] indicates that person ''from'' gave ''amount'' money to person ''to''. Return the minimum number of transactions required to settle all debts. First, compute the net balance for each person. Filter out people with a zero balance. Then, use backtracking or dynamic programming with bitmask to find the optimal combination of debt settlements that minimizes the total transaction count.','hard','https://leetcode.com/problems/optimal-account-balancing','{"Array","Dynamic Programming","Backtracking","Bitmask"}','{"affirm","amazon","citadel","goldman-sachs","google","intuit","microsoft","pinterest","rippling","salesforce","uber","zscaler"}',12,562.5,50.5,'3mo','gemini','[0.0067371493, -0.024978654, 0.0060786633, -0.06800269, -0.00039943735, -0.004838117, 0.022378962, 0.0062601427, 0.017538602, -0.0008308064, -0.001616107, -0.013372913, 0.020838639, 0.0148837175, 0.13307211, 0.016524807, 0.01772821, 0.023154214, 7.2975774e-05, -0.019980246, -0.024732443, -0.013794325, 0.017696997, -0.021998292, -0.0035201954, -0.011951395, 0.0045028813, 0.0059232083, 0.007024206, 0.013539402, 0.017495003, 0.029319515, 0.0008447759, 0.0377485, -0.0047876947, -0.01589597, 0.0052315504, -0.015318933, -0.0027169073, -0.00062682305, 0.005145364, -0.0037968678, 0.016602064, -0.01727251, -0.009088266, -0.0045373477, -0.009063206, -0.01019204, -0.019250935, 0.0081449235, 0.0113094505, -0.0021404403, 0.016403416, -0.17211555, 0.008327901, -0.0064708916, 0.013150093, -0.003307579, -0.02786351, -0.010055198, 0.0017856583, 0.0070460024, -0.006082557, -0.025768565, 0.004963522, -0.008651775, 0.012199462, 0.024921292, -0.0074883704, -0.026594857, 0.0069537843, -0.02