INSERT INTO problems (slug,leetcode_id,title,description,difficulty,source_url,topics,companies,company_count,popularity,acceptance,recency,description_source,embedding) VALUES ('number-of-distinct-islands',694,'Number of Distinct Islands','Given an m x n binary matrix grid where 1 represents land and 0 represents water, return the number of distinct islands. An island is a 4-directionally connected group of 1s. Two islands are considered the same if and only if one island can be translated (without rotation or reflection) to equal the other. Typical constraints: m and n are between 1 and 50, and grid elements are 0 or 1.','medium','https://leetcode.com/problems/number-of-distinct-islands','{"Depth-First Search","Breadth-First Search","Union Find","Hash Table","Matrix"}','{"amazon","anduril","aurora","bloomberg","coupang","google","microsoft","oracle","servicenow","snapchat","tiktok","walmart-labs"}',12,550.0,62.9,'30d','gemini','[-0.029966405, -0.008189321, -0.0012729627, -0.0748358, -0.018697873, -0.013497674, 0.0051683667, -0.0218742, 0.018012397, 0.012849682, -0.004331632, -0.007932484, -0.0047348426, 0.0119912485, 0.14229594, 0.021000879, -0.010726488, 0.006274285, 0.019252278, -0.012270318, 0.0008982176, -0.0096683465, 0.0003220265, -0.0068561058, -0.011829763, -0.03369427, -0.0040500835, 0.011947544, 0.017111683, -0.0022450313, -0.008307479, 0.04276982, 0.0059894435, 0.027263723, 0.0035176314, 0.0004337722, 0.023007344, 0.0044997567, -0.0085668145, 0.0012971871, -0.008941009, -0.012238403, 0.00478455, 0.005302885, -0.026940938, 0.021428779, -0.0057456563, -0.0161823, -0.010817468, 0.018122885, -0.027990889, 0.019974422, -0.018609537, -0.17922832, 0.0017957982, 0.0043816846, -0.0025133893, 0.0032741062, -0.016866159, -0.009849911, 0.014929059, 0.015302422, -0.019093957, -0.010276437, 0.009112653, -0.012398406, 0.01980206, 0.03203463, -0.0036286537, -0.017013224, 0.004939382, 0.006560121, -0.009815299, -0.03479267, 0.026354397, -0.015569721, 0.011579678, 0.0158