INSERT INTO problems (slug,leetcode_id,title,description,difficulty,source_url,topics,companies,company_count,popularity,acceptance,recency,description_source,embedding) VALUES ('candy-crush',723,'Candy Crush','Given an m x n integer matrix representing a Candy Crush board where positive integers denote different candy types, simulate the crushing process. If three or more candies of the same type are adjacent horizontally or vertically, mark them for crushing. Crush all marked candies simultaneously by changing their values to 0. Next, apply gravity so remaining candies drop down to fill any empty spaces (0s) within their columns. Repeat the crushing and dropping steps until no more candies can be crushed, then return the final state of the board. Constraints: m and n are between 3 and 50, and board[i][j] is between 1 and 2000.','medium','https://leetcode.com/problems/candy-crush','{"Array","Two Pointers","Matrix","Simulation"}','{"bloomberg","braze","capital-one","google","meta","pinterest","roblox","rubrik","tiktok","uber","visa"}',11,550.0,77.6,'3mo','gemini','[-0.014441923, 0.023528622, 0.0012350127, -0.0623995, -0.020337682, -0.0075094583, 0.008342296, -0.023131404, -0.0049868445, 0.008622966, 0.002900364, -0.0047575617, 0.014697485, -0.008544068, 0.13836719, 0.016842986, -0.022941712, 0.012001426, 0.029623913, 0.0113683175, 0.009154256, -0.006719654, 0.01119675, -0.003066973, -0.008983033, -0.008440032, -0.0002363458, 0.012453047, 0.030858746, 0.010959229, 0.0051504984, 0.02632611, 0.016434329, 0.044776477, -0.009267751, -0.03184002, 0.023509268, -0.0037575103, 0.003202427, -0.0008958833, -0.0051818867, 0.013170993, 0.024619646, 0.00024694356, 0.0016753381, 0.0056162677, 0.005800428, -0.01823958, -0.008344565, 0.014300595, -0.014773128, 0.006481749, -0.0011064414, -0.17826807, -0.0029633364, 0.003849577, 0.0075764544, -0.004575285, -0.013644007, -0.0065050237, 0.02257187, 0.009172324, -0.0014877548, -0.02256955, 0.010349395, 0.009346588, 0.031033553, 0.010857