INSERT INTO problems (slug,leetcode_id,title,description,difficulty,source_url,topics,companies,company_count,popularity,acceptance,recency,description_source,embedding) VALUES ('palindrome-partitioning',131,'Palindrome Partitioning','Given a string s , partition s such that every substring of the partition is a palindrome . Return all possible palindrome partitioning of s .

Example 1:

Input: s = "aab"
Output: [["a","a","b"],["aa","b"]]

Example 2:

Input: s = "a"
Output: [["a"]]

Constraints:

- 1 <= s.length <= 16

