INSERT INTO problems (slug,leetcode_id,title,description,difficulty,source_url,topics,companies,company_count,popularity,acceptance,recency,description_source,embedding) VALUES ('moving-average-from-data-stream',346,'Moving Average from Data Stream','Given a stream of integers and a window size, calculate the moving average of all integers in the current sliding window. Implement the MovingAverage class which is initialized with a window size and provides a next method that receives an integer from the stream, appends it to the window, and returns the moving average of the elements in the window. If the number of elements received so far is less than the window size, return the average of all elements processed so far.','easy','https://leetcode.com/problems/moving-average-from-data-stream','{"Array","Design","Queue","Data Stream"}','{"amazon","apple","arista-networks","bloomberg","citadel","google","indeed","meta","microsoft","qualcomm","spotify"}',11,512.5,80.2,'3mo','gemini','[-0.0065223468, -0.012754945, 0.044006575, -0.07365135, -0.045683086, -0.0031435697, 0.0051663946, -0.017201927, 0.033160586, -0.0036812753, -0.016527366, -0.009051237, 0.029121643, -0.003004285, 0.12693493, 0.023353115, -0.020304326, -0.006850464, -0.018466767, -0.025618078, -0.000668247, 0.025301794, 0.040533282, 0.0042971475, -0.019276384, -0.014938888, 0.0152808055, -0.02694854, 0.03684179, 0.010998105, -0.011852636, 0.021463262, 0.013246692, 0.009064094, -0.02609591, 0.01584535, 0.023563925, -0.007307122, -0.016835492, -0.00014302567, -0.008853676, -0.0021626689, 0.016105685, -0.024346827, -0.053667955, 0.008752544, -0.0020585519, -0.014099108, -0.018732756, -0.004736978, -0.0071491157, -0.0033070222, -0.023741864, -0.17562012, 0.016297273, 0.029609205, -0.0037865876, -0.018762622, -0.0130095435, -0.008815778, 0.0146078225, 0.01955613, -0.0019136831, 0.0015746208, -0.0054192175, -0.01196386, 0.026424251, 0.01941322, -0.020283882, -0.009740954, 0.018753843, 0.000101053134, 0.011714537, -0