INSERT INTO problems (slug,leetcode_id,title,description,difficulty,source_url,topics,companies,company_count,popularity,acceptance,recency,description_source,embedding) VALUES ('minimum-number-of-steps-to-make-two-strings-anagram',1347,'Minimum Number of Steps to Make Two Strings Anagram','You are given two strings of the same length s and t . In one step you can choose any character of t and replace it with another character .

Return the minimum number of steps to make t an anagram of s .

An Anagram of a string is a string that contains the same characters with a different (or the same) ordering.

Example 1:

Input: s = "bab", t = "aba"
Output: 1
Explanation: Replace the first ''a'' in t with b, t = "bba" which is anagram of s.

Example 2:

Input: s = "leetcode", t = "practice"
Output: 5
Explanation: Replace ''p'', ''r'', ''a'', ''i'' and ''c'' from t with proper characters to make t anagram of s.

Example 3:

Input: s = "anagram", t = "mangaar"
Output: 0
Explanation: "anagram" and "mangaar" are anagrams.

Constraints:

- 1 <= s.length <= 5 * 10^4

- s.length == t.length

- s and t consist of lowercase English letters only.','medium','https://leetcode.com/problems/minimum-number-of-steps-to-make-two-strings-anagram','{"Hash Table","String","Counting"}','{"amazon","bloomberg","doordash","google","ixl","jpmorgan","microsoft","oracle","sofi","twitter"}',10,512.5,82.6,'older','leetcode','[-0.008383927, -0.003875328, 0.0037506397, -0.062045857, -0.017653098, 0.022745296, 0.0064916867, 0.012816463, -0.0016060218, -0.02193198, -0.010669456, -0.000501848, 0.008470839, 0.006757991, 0.15672602, -0.0039351503, -0.028456552, 0.016397605, 0.009697306, -0.00730716, -0.01891694, 0.027540628, 0.004046474, -0.0049495576, -0.0036090906, -0.023416674, -0.0012068484, -0.0020804284, 0.013913633, 0.009330221, -0.008479108, 0.024029585, 0.020640118, 0.024218831, 0.0017021011, -0.0032597, 0.035645545, 0.0052512228, -8.182152e-05, 0.011769925, 0.0071410355, -0.0018881181, 0.031162895, -0.017785762, -0.010095394, -0.0033144262, 0.020836832, 0.009522968, -0.013190692, -0.0009918188, -0.0063598086, 0.0026790558, -0.026472863, -0.18292011, 0.014089075, -0.006263495, -0.023191461, -0.0039960314, -0.02562128, -0.0020384074, 0.0037376217, 0.032641593, 0.0020769124, 0.003994501, 0.014201277, -0.022952903, 0.005959192, 0.025621196, -0.018254563, 0.00063600653, 0.016364964, -0.014379983, -0.0068992763, -0.018724365, 0.01096024, -0.028821848, 0.0041498137, 0.0052825245, -0.0061067594, 0.005387965, -0.0055439845, 0.017172102, -0.02210433, -0.0038213204, -0.0029200525, 0.004143721, -0.055483602, 0.0017785901, -0.017824406, -0.023331473, -0.0012903822, -0.007705135, 0.022623397, 0.0028056293, -0.005488663, -0.013214472, 0.022137925, 0.015940133, 0.007260131, -0.0146338735, 0.005032218, -0.010705696, -0.010673152, 0.00073587283, 0.010499042, -0.02933425, 0.005834881, -0.020872088, 0.02878556, 0.010280977, 0.0025899825, -0.023970729, 0.0047324933, -0.003609166, 0.011035978, -0.12744406, -0.021239627, -0.0039406274, -0.027557539, -0.010748032, -0.026704809, -0.021553025, 0.0