INSERT INTO problems (slug,leetcode_id,title,description,difficulty,source_url,topics,companies,company_count,popularity,acceptance,recency,description_source,embedding) VALUES ('reconstruct-original-digits-from-english',423,'Reconstruct Original Digits from English','Given a string s containing an out-of-order English representation of digits 0-9 , return the digits in ascending order .

Example 1:

Input: s = "owoztneoer"
Output: "012"

Example 2:

Input: s = "fviefuro"
Output: "45"

Constraints:

- 1 <= s.length <= 10^5

- s[i] is one of the characters ["e","g","f","i","h","o","n","s","r","u","t","w","v","x","z"] .

